    56
    57  KArchive::KArchive(const QString &fileName)
    58      : d(new KArchivePrivate)
    59  {
    60      if (fileName.isEmpty()) {
    61          qCWarning(KArchiveLog) << "KArchive: No file name specified";
    62      }
    63      d->fileName = fileName;
    64      // This constructor leaves the device set to 0.
    65      // This is for the use of QSaveFile, see open().
    66  }
    67
    68  KArchive::KArchive(QIODevice *dev)
    69      : d(new KArchivePrivate)
    70  {
    71      if (!dev) {
    72          qCWarning(KArchiveLog) << "KArchive: Null device specified";
    73      }
    74      d->dev = dev;
    75  }
    76
    77  KArchive::~KArchive()
    78  {
    79      Q_ASSERT(!isOpen()); // the derived class destructor must have closed already
    80      delete d;
    81  }
    82
    83  bool KArchive::open(QIODevice::OpenMode mode)
    84  {
    85      Q_ASSERT(mode != QIODevice::NotOpen);
    86
    87      if (isOpen()) {
    88          close();
    89      }
    90
    91      if (!d->fileName.isEmpty()) {
    92          Q_ASSERT(!d->dev);
    93          if (!createDevice(mode)) {
    94              return false;
    95          }
    96      }
    97
    98      if (!d->dev) {
    99          setErrorString(tr("No filename or device was specified"));
   100          return false;
   101      }
   102
   103      if (!d->dev->isOpen() && !d->dev->open(mode)) {
   104          setErrorString(tr("Could not set device mode to %1").arg(mode));
   105          return false;
   106      }
   107
   108      d->mode = mode;
   109
   110      Q_ASSERT(!d->rootDir);
   111      d->rootDir = nullptr;
   112
   113      return openArchive(mode);
   114  }
   115
   116  bool KArchive::createDevice(QIODevice::OpenMode mode)
   117  {
   118      switch (mode) {
   119      case QIODevice::WriteOnly:
   120          if (!d->fileName.isEmpty()) {
   121              // The use of QSaveFile can't be done in the ctor (no mode known yet)
   122              //qCDebug(KArchiveLog) << "Writing to a file using QSaveFile";
   123              d->saveFile = new QSaveFile(d->fileName);
   124              if (!d->saveFile->open(QIODevice::WriteOnly)) {
   125                  setErrorString(
   126                      tr("QSaveFile creation for %1 failed: %2")
   127                          .arg(d->fileName, d->saveFile->errorString()));
   128
   129                  delete d->saveFile;
   130                  d->saveFile = nullptr;
   131                  return false;
   132              }
   133              d->dev = d->saveFile;
   134              Q_ASSERT(d->dev);
   135          }
   136          break;
   137      case QIODevice::ReadOnly:
   138      case QIODevice::ReadWrite:
   139          // ReadWrite mode still uses QFile for now; we'd need to copy to the tempfile, in fact.
   140          if (!d->fileName.isEmpty()) {
   141              d->dev = new QFile(d->fileName);
   142              d->deviceOwned = true;
   143          }
   144          break; // continued below
   145      default:
   146          setErrorString(tr("Unsupported mode %1").arg(d->mode));
   147          return false;
   148      }
   149      return true;
   150  }
   151
   152  bool KArchive::close()
   153  {
   154      if (!isOpen()) {
   155          setErrorString(tr("Archive already closed"));
   156          return false;    // already closed (return false or true? arguable...)
   157      }
   158
   159      // moved by holger to allow kzip to write the zip central dir
   160      // to the file in closeArchive()
   161      // DF: added d->dev so that we skip closeArchive if saving aborted.
   162      bool closeSucceeded = true;
   163      if (d->dev) {
   164          closeSucceeded = closeArchive();
   165          if (d->mode == QIODevice::WriteOnly && !closeSucceeded) {
   166              d->abortWriting();
   167          }
   168      }
   169
   170      if (d->dev && d->dev != d->saveFile) {
   171          d->dev->close();
   172      }
   173
   174      // if d->saveFile is not null then it is equal to d->dev.
   175      if (d->saveFile) {
   176          closeSucceeded = d->saveFile->commit();
   177          delete d->saveFile;
   178          d->saveFile = nullptr;
   179      }
   180      if (d->deviceOwned) {
   181          delete d->dev; // we created it ourselves in open()
   182      }
   183
   184      delete d->rootDir;
   185      d->rootDir = nullptr;
   186      d->mode = QIODevice::NotOpen;
   187      d->dev = nullptr;
   188      return closeSucceeded;
   189  }
